TRUNCATE TABLE public.bus_stops;

CREATE TEMP TABLE bus_stops_staging (
    stop_id   VARCHAR(255),
    name      VARCHAR(255),
    node_no   VARCHAR(255),
    city_code INTEGER,
    lat       DOUBLE PRECISION,
    lng       DOUBLE PRECISION
);


SELECT stop_id, name, NULLIF(node_no, ''), city_code, ST_SetSRID(ST_MakePoint(lng, lat), 4326)
FROM bus_stops_staging;

DROP TABLE bus_stops_staging;
